const features={deck:['Прочная дека','Широкая платформа и рельефное покрытие помогают уверенно поставить ноги во время поездки.'],folding:['Складной механизм','Узел складывания соединяет рулевую стойку с рамой. Перед поездкой проверяйте фиксацию механизма.'],display:['Информативный дисплей','Контролируйте скорость, заряд и выбранный режим на дисплее. Набор функций зависит от конкретной модели.']};document.querySelectorAll('[data-feature]').forEach(button=>button.addEventListener('click',()=>{const [title,text]=features[button.dataset.feature];document.querySelector('#info-content').innerHTML=`<span class="eyebrow">МОЩНОСТЬ В ДЕТАЛЯХ</span><h2>${title}</h2><p>${text}</p><a class="button yellow" href="panel.html">Выбрать модель </a>`;document.querySelector('#info-dialog').showModal();}));
const showcase=document.querySelector('.precision-hero');
if(showcase){
 const slides=[{title:'KUGOO<br>G3 PRO',caption:'СОЗДАН ДЛЯ БОЛЬШИХ<br>ВОЗМОЖНОСТЕЙ',scene:'assets/studio-g3-portrait.webp',image:'assets/showroom-g3-complete.webp',type:'Электросамокат',name:'KuKirin G3 Pro',model:'g3'}, {title:'KUGOO<br>WISH 01',caption:'БОЛЬШЕ СВОБОДЫ<br>ЗА ПРЕДЕЛАМИ АСФАЛЬТА',scene:'assets/studio-wish-portrait.webp',image:'assets/category-wish-cutout.png',type:'Электромотоцикл',name:'KUGOO WISH 01',model:'wish'}, {title:'KUGOO<br>V3',caption:'НОВЫЕ МАРШРУТЫ<br>КАЖДЫЙ ДЕНЬ',scene:'assets/studio-v3-portrait.webp',image:'assets/showroom-v3-complete.webp',type:'Электровелосипед',name:'KUGOO V3',model:'v3'}];
 let current=0;
 function displaySlide(index){current=index;const s=slides[index];showcase.querySelector('h1').innerHTML=s.title;showcase.querySelector('.precision-subtitle').innerHTML=s.caption;const object=showcase.querySelector('.slide-product');object.hidden=!s.image;if(s.image){object.querySelector('img').src=s.image;object.querySelector('img').alt=s.name;}showcase.dataset.slide=index;showcase.closest('.whole-showroom').style.setProperty('--room-scene',`url('${s.scene}')`);showcase.style.setProperty('--slide-image',s.image?`url('${s.image}')`:"url('assets/precision-hero.png')");showcase.querySelector('.precision-copy .button').href=s.model?'panel.html?model='+s.model:'catalog.html?type='+encodeURIComponent(s.type);const metrics=showcase.querySelector('.precision-specs');metrics.hidden=index!==0;document.querySelectorAll('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.slide)===index)));}
 document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>displaySlide(Number(b.dataset.slide)));
 let touchX=null;showcase.addEventListener('touchstart',e=>{touchX=e.touches[0].clientX},{passive:true});showcase.addEventListener('touchend',e=>{if(touchX===null)return;const distance=e.changedTouches[0].clientX-touchX;if(Math.abs(distance)>65)displaySlide((current+(distance<0?1:2))%3);touchX=null},{passive:true});
 displaySlide(0);
 showcase.tabIndex=0;showcase.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();displaySlide((current+(e.key==='ArrowRight'?1:2))%3);}});
}
